                var pattern = try allocator.alloc(u8, size);
                _ = &pattern;
                _ = @memcpy(pattern[0..pattern_expr.data.len], pattern_expr.data);
                _ = @memcpy(pattern[pattern_expr.data.len..size], "/package.json");
                _ = try out_patterns.append(pattern);
},
else => {
_ = Output.prettyErrorln("<r><red>error<r>: Failed to parse \"workspaces\" property: all items must be strings", .{});
                _ = Global.exit(1);
},
}
            }
            const parent_trimmed = strings.withoutTrailingSlash(workdir);
            _ = @memcpy(root_buf[0..parent_trimmed.len], parent_trimmed);
            return root_buf[0..parent_trimmed.len];
        }
        _ = try out_patterns.append(try allocator.dupe(u8, "**/package.json"));
        const root_dir = strings.withoutTrailingSlash(workdir_);
        _ = @memcpy(root_buf[0..root_dir.len], root_dir);
        return root_buf[0..root_dir.len];
}
